/// Create a router mounting both `TestService` and `BenchmarkService`.
/// `max_response_body` raises the generated-response cap for
/// large-payload runs; `None` keeps the 4 MiB demo default.
pub fn create_dual_server(max_response_body: Option<usize>) -> pbrs_grpc::Router {
    benchmark_service::dual_router(max_response_body)
}

/// Call shape driven by the `load` subcommand (SB-11 stack-matrix cells).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LoadShape {
    /// One `TestService.UnaryCall` (or `BenchmarkService.UnaryCall`) per RPC.
    Unary,
    /// One `TestService.StreamingOutputCall` draining every response per RPC.
    ServerStream,
    /// One lockstep `TestService.FullDuplexCall` ping-pong exchange per RPC.
    Bidi,
    /// One `TestService.StreamingInputCall` uploading `stream_msgs`
    /// requests of `req_bytes` each per RPC.
    ClientStream,
}

impl std::str::FromStr for LoadShape {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "unary" => Ok(LoadShape::Unary),
            "server_stream" | "server-stream" | "stream" => Ok(LoadShape::ServerStream),
            "bidi" | "ping_pong" | "ping-pong" => Ok(LoadShape::Bidi),
            "client_stream" | "client-stream" | "upload" => Ok(LoadShape::ClientStream),
            other => Err(format!(
                "unknown load shape '{other}': expected unary, server_stream, bidi, or client_stream"
            )),
        }
    }
}

impl std::fmt::Display for LoadShape {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            LoadShape::Unary => write!(f, "unary"),
            LoadShape::ServerStream => write!(f, "server_stream"),
            LoadShape::Bidi => write!(f, "bidi"),
            LoadShape::ClientStream => write!(f, "client_stream"),
        }
    }
}

/// Client transport driven by the `load` subcommand.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LoadTransport {
    Native,
    Tonic,
}

impl std::str::FromStr for LoadTransport {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "native" => Ok(LoadTransport::Native),
            "tonic" => Ok(LoadTransport::Tonic),
            other => Err(format!(
                "unknown load transport '{other}': expected native or tonic"
            )),
        }
    }
}

impl std::fmt::Display for LoadTransport {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            LoadTransport::Native => write!(f, "native"),
            LoadTransport::Tonic => write!(f, "tonic"),
        }
    }
}

/// Largest request/response payload the `load` subcommand will allocate.
/// SB-11 cells peak at 64 KiB; anything past this is a typo, not a cell.
pub const LOAD_MAX_PAYLOAD_BYTES: usize = 64 * 1024 * 1024;

/// CLI options for load generation.
#[derive(Debug, Clone, PartialEq)]
pub struct LoadCliArgs {
    pub distribution: Option<load::LoadDistribution>,
    pub rate: Option<f64>,
    pub seed: Option<u64>,
    pub max_in_flight: Option<usize>,
    pub duration_secs: Option<f64>,
    pub server_addr: Option<String>,
    pub output_file: Option<String>,
    pub print_json: bool,
    pub quick: bool,
    pub benchmark_service: bool,
    pub shape: Option<LoadShape>,
    pub req_bytes: Option<usize>,
    pub resp_bytes: Option<usize>,
    pub stream_msgs: Option<u32>,
    pub transport: Option<LoadTransport>,
    pub tls_ca: Option<String>,
    pub tls_server_name: Option<String>,
    pub max_message_size: Option<usize>,
    pub connections: Option<usize>,
}

fn get_arg_val(args: &[String], flag: &str) -> Option<String> {
    for i in 0..args.len() {
        if let Some(val) = args[i].strip_prefix(&format!("{flag}=")) {
            return Some(val.to_string());
        }
        if args[i] == flag && i + 1 < args.len() && !args[i + 1].starts_with('-') {
            return Some(args[i + 1].clone());
        }
    }
    None
}

fn has_flag(args: &[String], flag: &str) -> bool {
    args.iter()
        .any(|a| a == flag || a.starts_with(&format!("{flag}=")))
}

/// Parse load generator options from command-line arguments.
pub fn parse_load_cli_args(args: &[String]) -> Result<LoadCliArgs, String> {
    let distribution = if let Some(val) = get_arg_val(args, "--distribution") {
        Some(val.parse::<load::LoadDistribution>()?)
    } else {
        None
    };

    let rate = if let Some(val) = get_arg_val(args, "--rate") {
        let r: f64 = val
            .parse()
            .map_err(|e| format!("invalid --rate '{val}': {e}"))?;
        if r <= 0.0 {
            return Err(format!("invalid --rate '{val}': must be strictly positive"));
        }
        Some(r)
    } else {
        None
    };

    let seed = if let Some(val) = get_arg_val(args, "--seed") {
        let s: u64 = val
            .parse()
            .map_err(|e| format!("invalid --seed '{val}': {e}"))?;
        Some(s)
    } else {
        None
    };

    let max_in_flight = if let Some(val) =
        get_arg_val(args, "--max-in-flight").or_else(|| get_arg_val(args, "--max_in_flight"))
    {
        let m: usize = val
            .parse()
            .map_err(|e| format!("invalid --max-in-flight '{val}': {e}"))?;
        if m == 0 {
            return Err(format!(
                "invalid --max-in-flight '{val}': must be at least 1"
            ));
        }
        Some(m)
    } else {
        None
    };

    let duration_secs = if let Some(val) = get_arg_val(args, "--duration-secs")
        .or_else(|| get_arg_val(args, "--duration_secs"))
        .or_else(|| get_arg_val(args, "--duration"))
    {
        let d: f64 = val
            .parse()
            .map_err(|e| format!("invalid duration '{val}': {e}"))?;
        if d <= 0.0 {
            return Err(format!(
                "invalid duration '{val}': must be strictly positive"
            ));
        }
        Some(d)
    } else {
        None
    };

    let server_addr = get_arg_val(args, "--server_addr")
        .or_else(|| get_arg_val(args, "--server-addr"))
        .or_else(|| get_arg_val(args, "--serveraddr"))
        .or_else(|| get_arg_val(args, "--target"));

    let output_file = get_arg_val(args, "--output")
        .or_else(|| get_arg_val(args, "-o"))
        .or_else(|| get_arg_val(args, "--report"));

    let print_json = has_flag(args, "--json");
    let quick = has_flag(args, "--quick") || has_flag(args, "-q");
    let benchmark_service = has_flag(args, "--benchmark-service")
        || has_flag(args, "--benchmark_service")
        || get_arg_val(args, "--service").as_deref() == Some("benchmark");

    // `--shape` also belongs to the `client`/`server`/`smoke` roles with a
    // different vocabulary (all/qps/upload); only the `load` role owns the
    // LoadShape values parsed here.
    let shape = if args.get(1).map(String::as_str) == Some("load") {
        if let Some(val) = get_arg_val(args, "--shape") {
            Some(val.parse::<LoadShape>()?)
        } else {
            None
        }
    } else {
        None
    };

    let parse_bytes = |flag: &str| -> Result<Option<usize>, String> {
        if let Some(val) = get_arg_val(args, flag) {
            let n: usize = val
                .parse()
                .map_err(|e| format!("invalid {flag} '{val}': {e}"))?;
            if n > LOAD_MAX_PAYLOAD_BYTES {
                return Err(format!(
                    "invalid {flag} '{val}': exceeds {LOAD_MAX_PAYLOAD_BYTES} bytes"
                ));
            }
            Ok(Some(n))
        } else {
            Ok(None)
        }
    };
    let req_bytes = parse_bytes("--req-bytes")?;
    let resp_bytes = parse_bytes("--resp-bytes")?;

    let stream_msgs = if let Some(val) =
        get_arg_val(args, "--stream-msgs").or_else(|| get_arg_val(args, "--stream_msgs"))
    {
        let n: u32 = val
            .parse()
            .map_err(|e| format!("invalid --stream-msgs '{val}': {e}"))?;
        if n == 0 {
            return Err(format!("invalid --stream-msgs '{val}': must be at least 1"));
        }
        Some(n)
    } else {
        None
    };

    let transport = if let Some(val) = get_arg_val(args, "--transport") {
        Some(val.parse::<LoadTransport>()?)
    } else {
        None
    };

    let connections = get_arg_val(args, "--connections")
        .or_else(|| get_arg_val(args, "--conns"))
        .map(|val| {
            val.parse::<usize>()
                .map_err(|e| format!("invalid --connections '{val}': {e}"))
        })
        .transpose()?;
    if connections.is_some_and(|n| n == 0 || n > 256) {
        return Err("invalid --connections: want 1..=256".to_string());
    }

    let tls_ca = get_arg_val(args, "--tls-ca").or_else(|| get_arg_val(args, "--tls_ca"));
    let tls_server_name =
        get_arg_val(args, "--tls-server-name").or_else(|| get_arg_val(args, "--tls_server_name"));
    if tls_ca.is_some() != tls_server_name.is_some() {
        return Err(
            "TLS needs both --tls-ca and --tls-server-name (verification is not optional)"
                .to_string(),
        );
    }
    if tls_ca.is_some() && transport == Some(LoadTransport::Tonic) {
        return Err(
            "tonic transport has no TLS support in rpc-bench: tonic 0.14 TLS pulls a C crypto provider, \
             conflicting with the pure-Rust dependency policy; use --transport=native for TLS cells"
                .to_string(),
        );
    }
    if benchmark_service && transport == Some(LoadTransport::Tonic) {
        return Err(
            "tonic transport cannot drive --benchmark-service (no tonic BenchmarkService client); \
             use TestService shapes or --transport=native"
                .to_string(),
        );
    }
    if benchmark_service && shape.is_some_and(|s| s != LoadShape::Unary) {
        return Err(
            "--benchmark-service only supports --shape=unary (BenchmarkService has no streaming methods)"
                .to_string(),
        );
    }

    let max_message_size = if let Some(val) =
        get_arg_val(args, "--max-message-size").or_else(|| get_arg_val(args, "--max_message_size"))
    {
        let n: usize = val
            .parse()
            .map_err(|e| format!("invalid --max-message-size '{val}': {e}"))?;
        if n == 0 || n > 1024 * 1024 * 1024 {
            return Err(format!(
                "invalid --max-message-size '{val}': want 1..=1073741824"
            ));
        }
        Some(n)
    } else {
        None
    };

    Ok(LoadCliArgs {
        distribution,
        rate,
        seed,
        max_in_flight,
        duration_secs,
        server_addr,
        output_file,
        print_json,
        quick,
        benchmark_service,
        shape,
        req_bytes,
        resp_bytes,
        stream_msgs,
        transport,
        tls_ca,
        tls_server_name,
        max_message_size,
        connections,
    })
}

pub fn extended_usage() -> String {
    format!(
        "{}\n\
         Load generator options:\n  \
           --distribution <MODE>    Load distribution: closed, constant, or poisson (default: closed)\n  \
           --rate <QPS>             Target offered rate in queries per second (for constant/poisson)\n  \
           --seed <SEED>            Random seed for Poisson arrival schedule\n  \
           --max-in-flight <CAP>    Maximum in-flight calls before queue overflow (default: 1000)\n  \
           --duration-secs <SECS>   Duration of load test in seconds\n  \
           --benchmark-service      Target BenchmarkService.UnaryCall instead of TestService.UnaryCall\n  \
           --shape <SHAPE>          Load call shape: unary, server_stream, bidi, client_stream (default: unary)\n  \
           --req-bytes <N>          Unary request payload bytes (default: 0)\n  \
           --resp-bytes <N>         Unary response bytes, or bytes per streaming message (default: 0; 1024 with --benchmark-service)\n  \
           --stream-msgs <N>        Messages per streaming RPC (default: 2000 server_stream, 256 bidi)\n  \
           --transport <MODE>       Load client transport: native or tonic (default: native; tonic is plaintext only)\n  \
           --tls-ca <PATH>          PEM CA to verify the server (requires --tls-server-name; native only)\n  \
           --tls-server-name <N>    Server name to verify against the CA\n  \
           --max-message-size <N>   Max decoded message bytes (default: transport default, 4 MiB)\n  \
           --connections <N>        Client connections to pool over (default: 1)\n\
         Worker options:\n  \
           worker                   Run official gRPC WorkerService\n  \
           --driver_port <PORT>     Port to listen on for benchmark driver (default: 10010)\n  \
         RT-07 diagnostic:\n  \
           fairness --scenario rpc-bench/scenarios/fairness.json [--smoke] [--output <PATH>] [--require-qualified]\n  \
                                    Separate-process native/native bulk + scheduled unary; never a qualification pass\n",
        process::usage()
    )
}

/// Connect a native channel, plaintext or TLS-verified against a CA.
async fn load_native_channel(
    addr: SocketAddr,
    tls_ca: Option<&str>,
    tls_server_name: Option<&str>,
    max_message_size: Option<usize>,
    connections: usize,
) -> Result<pbrs_grpc::Channel, String> {
    let config = pbrs_grpc::ChannelConfig::default().connections(connections);
    let channel = match (tls_ca, tls_server_name) {
        (Some(ca_path), Some(name)) => {
            let ca_pem = std::fs::read(ca_path)
                .map_err(|e| format!("failed to read --tls-ca '{ca_path}': {e}"))?;
            let tls = pbrs_grpc::ClientTls::ca(name, &ca_pem)
                .map_err(|e| format!("invalid TLS config: {e}"))?;
            pbrs_grpc::Channel::connect_tls_with(addr, config, tls)
                .await
                .map_err(|e| format!("TLS connect to {addr} as {name}: {e}"))?
        }
        _ => pbrs_grpc::Channel::connect_with(addr, config)
            .await
            .map_err(|e| format!("failed to connect to {addr}: {e}"))?,
    };
    Ok(match max_message_size {
        Some(n) => channel.max_decoding_message_size(n),
        None => channel,
    })
}

fn unary_request(req_bytes: usize, resp_bytes: usize) -> pbrs_grpc::SimpleRequest {
    let mut req = pbrs_grpc::SimpleRequest::new();
    if req_bytes > 0 {
        let mut payload = pbrs_grpc::Payload::new();
        payload.set_body(vec![0u8; req_bytes]);
        req.set_payload(payload);
    }
    req.set_response_size(resp_bytes as i32);
    req
}

fn unary_tonic_request(req_bytes: usize, resp_bytes: usize) -> tonic_gen::SimpleRequest {
    let mut req = tonic_gen::SimpleRequest::new();
    if req_bytes > 0 {
        let mut payload = tonic_gen::Payload::new();
        payload.set_body(vec![0u8; req_bytes]);
        req.set_payload(payload);
    }
    req.set_response_size(resp_bytes as i32);
    req
}

fn bidi_request(resp_bytes: usize) -> pbrs_grpc::StreamingOutputCallRequest {
    let mut req = pbrs_grpc::StreamingOutputCallRequest::new();
    let mut p = pbrs_grpc::ResponseParameters::new();
    p.set_size(resp_bytes as i32);
    req.response_parameters_mut().push(p);
    req
}

fn bidi_tonic_request(resp_bytes: usize) -> tonic_gen::StreamingOutputCallRequest {
    let mut req = tonic_gen::StreamingOutputCallRequest::new();
    let mut p = tonic_gen::ResponseParameters::new();
    p.set_size(resp_bytes as i32);
    req.response_parameters_mut().push(p);
    req
}

#[allow(clippy::too_many_arguments)]
async fn run_load_native(
    load_gen: &load::LoadGenerator,
    addr: SocketAddr,
    tls_ca: Option<&str>,
    tls_server_name: Option<&str>,
    shape: LoadShape,
    req_bytes: usize,
    resp_bytes: usize,
    stream_msgs: u32,
    benchmark_service: bool,
    max_message_size: Option<usize>,
    connections: usize,
) -> Result<load::LoadRecord, String> {
    let channel =
        load_native_channel(addr, tls_ca, tls_server_name, max_message_size, connections).await?;
    match (shape, benchmark_service) {
        (LoadShape::Unary, true) => {
            let client = benchmark_service::BenchmarkServiceClient::new(channel);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    async move {
                        let mut req = benchmark_service::SimpleRequest::new();
                        if req_bytes > 0 {
                            let mut payload = benchmark_service::Payload::new();
                            payload.set_body(vec![0u8; req_bytes]);
                            req.set_payload(payload);
                        }
                        req.set_response_size(resp_bytes as i32);
                        let resp = client
                            .unary_call(pbrs_grpc::Request::new(req))
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?;
                        let got = resp.into_inner().payload().body().len();
                        if got != resp_bytes {
                            return Err(load::RpcCallError::Other(format!(
                                "response size mismatch: got {got}, want {resp_bytes}"
                            )));
                        }
                        Ok(())
                    }
                })
                .await)
        }
        (LoadShape::Unary, false) => {
            let client = pbrs_grpc::TestServiceClient::new(channel);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    async move {
                        let resp = client
                            .unary_call(pbrs_grpc::Request::new(unary_request(
                                req_bytes, resp_bytes,
                            )))
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?;
                        let got = resp.into_inner().payload().body().len();
                        if got != resp_bytes {
                            return Err(load::RpcCallError::Other(format!(
                                "response size mismatch: got {got}, want {resp_bytes}"
                            )));
                        }
                        Ok(())
                    }
                })
                .await)
        }
        (LoadShape::ServerStream, _) => {
            let client = pbrs_grpc::TestServiceClient::new(channel);
            let template = process::stream_kernel_req(stream_msgs as i32, resp_bytes as i32);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    let template = template.clone();
                    async move {
                        let mut inbound = client
                            .streaming_output_call(pbrs_grpc::Request::new(template))
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .into_inner();
                        let mut n = 0u32;
                        while let Some(msg) = inbound
                            .message()
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                        {
                            if msg.payload().body().len() != resp_bytes {
                                return Err(load::RpcCallError::Other(format!(
                                    "stream msg {n} size mismatch: got {}, want {resp_bytes}",
                                    msg.payload().body().len()
                                )));
                            }
                            n += 1;
                        }
                        if n != stream_msgs {
                            return Err(load::RpcCallError::Other(format!(
                                "stream count mismatch: got {n}, want {stream_msgs}"
                            )));
                        }
                        Ok(())
                    }
                })
                .await)
        }
        (LoadShape::ClientStream, _) => {
            let client = pbrs_grpc::TestServiceClient::new(channel);
            let template = process::upload_kernel_req(req_bytes as i32);
            let want = process::upload_want_bytes(stream_msgs as i32, req_bytes as i32);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    let template = template.clone();
                    async move {
                        let (tx, call) = client.streaming_input_call(pbrs_grpc::Request::new(()));
                        let send = async move {
                            for i in 0..stream_msgs {
                                tx.send(template.clone()).await.map_err(|e| {
                                    load::RpcCallError::Other(format!("upload send msg {i}: {e}"))
                                })?;
                            }
                            tx.close();
                            Ok::<(), load::RpcCallError>(())
                        };
                        let (send_res, resp_res) = tokio::join!(send, call);
                        send_res?;
                        let got = resp_res
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .into_inner()
                            .aggregated_payload_size();
                        if got != want {
                            return Err(load::RpcCallError::Other(format!(
                                "upload aggregate mismatch: got {got}, want {want}"
                            )));
                        }
                        Ok(())
                    }
                })
                .await)
        }
        (LoadShape::Bidi, _) => {
            let client = pbrs_grpc::TestServiceClient::new(channel);
            let template = bidi_request(resp_bytes);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    let template = template.clone();
                    async move {
                        let (tx, call) = client.full_duplex_call(pbrs_grpc::Request::new(()));
                        let mut inbound = call
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .into_inner();
                        for i in 0..stream_msgs {
                            tx.send(template.clone()).await.map_err(|e| {
                                load::RpcCallError::Other(format!("bidi send pair {i}: {e}"))
                            })?;
                            let reply = inbound
                                .message()
                                .await
                                .map_err(|e| {
                                    load::RpcCallError::Other(format!("bidi recv pair {i}: {e}"))
                                })?
                                .ok_or_else(|| {
                                    load::RpcCallError::Other(format!(
                                        "bidi stream ended early at pair {i}"
                                    ))
                                })?;
                            if reply.payload().body().len() != resp_bytes {
                                return Err(load::RpcCallError::Other(format!(
                                    "bidi pair {i} size mismatch: got {}, want {resp_bytes}",
                                    reply.payload().body().len()
                                )));
                            }
                        }
                        tx.close();
                        while inbound
                            .message()
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .is_some()
                        {
                            return Err(load::RpcCallError::Other(
                                "bidi unexpected extra message after close".to_string(),
                            ));
                        }
                        Ok(())
                    }
                })
                .await)
        }
    }
}

fn tonic_load_client(
    channel: tonic::transport::Channel,
    max_message_size: Option<usize>,
) -> tonic_gen::TestServiceClient<tonic::transport::Channel> {
    let client = tonic_gen::TestServiceClient::new(channel);
    match max_message_size {
        Some(n) => client.max_decoding_message_size(n),
        None => client,
    }
}

async fn run_load_tonic(
    load_gen: &load::LoadGenerator,
    addr: SocketAddr,
    shape: LoadShape,
    req_bytes: usize,
    resp_bytes: usize,
    stream_msgs: u32,
    max_message_size: Option<usize>,
    connections: usize,
) -> Result<load::LoadRecord, String> {
    // Pool like the native client: one h2 driver task per connection on
    // both sides, or the peer comparison measures client framing.
    let channel = if connections <= 1 {
        process::tonic_channel(addr).await?
    } else {
        let mut endpoints = Vec::with_capacity(connections);
        for _ in 0..connections {
            endpoints.push(process::fair_tonic_endpoint(format!("http://{addr}"))?);
        }
        tonic::transport::Channel::balance_list(endpoints.into_iter())
    };
    match shape {
        LoadShape::Unary => {
            let client = tonic_load_client(channel, max_message_size);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    async move {
                        let mut client = client;
                        let resp = client
                            .unary_call(tonic::Request::new(unary_tonic_request(
                                req_bytes, resp_bytes,
                            )))
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?;
                        let got = resp.into_inner().payload().body().len();
                        if got != resp_bytes {
                            return Err(load::RpcCallError::Other(format!(
                                "response size mismatch: got {got}, want {resp_bytes}"
                            )));
                        }
                        Ok(())
                    }
                })
                .await)
        }
        LoadShape::ServerStream => {
            let client = tonic_load_client(channel, max_message_size);
            let template = process::stream_tonic_req(stream_msgs as i32, resp_bytes as i32);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    let template = template.clone();
                    async move {
                        let mut client = client;
                        let mut inbound = client
                            .streaming_output_call(tonic::Request::new(template))
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .into_inner();
                        let mut n = 0u32;
                        while let Some(msg) = inbound
                            .message()
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                        {
                            if msg.payload().body().len() != resp_bytes {
                                return Err(load::RpcCallError::Other(format!(
                                    "stream msg {n} size mismatch: got {}, want {resp_bytes}",
                                    msg.payload().body().len()
                                )));
                            }
                            n += 1;
                        }
                        if n != stream_msgs {
                            return Err(load::RpcCallError::Other(format!(
                                "stream count mismatch: got {n}, want {stream_msgs}"
                            )));
                        }
                        Ok(())
                    }
                })
                .await)
        }
        LoadShape::ClientStream => {
            let client = tonic_load_client(channel, max_message_size);
            let template = process::upload_tonic_req(req_bytes as i32);
            let want = process::upload_want_bytes(stream_msgs as i32, req_bytes as i32);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    let template = template.clone();
                    async move {
                        let mut client = client;
                        let (tx, rx) = tokio::sync::mpsc::channel(8);
                        let send = async move {
                            for i in 0..stream_msgs {
                                tx.send(template.clone()).await.map_err(|_| {
                                    load::RpcCallError::Other(format!("upload send msg {i} failed"))
                                })?;
                            }
                            drop(tx);
                            Ok::<(), load::RpcCallError>(())
                        };
                        let recv = client.streaming_input_call(tonic::Request::new(
                            tokio_stream::wrappers::ReceiverStream::new(rx),
                        ));
                        let (send_res, resp_res) = tokio::join!(send, recv);
                        send_res?;
                        let got = resp_res
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .into_inner()
                            .aggregated_payload_size();
                        if got != want {
                            return Err(load::RpcCallError::Other(format!(
                                "upload aggregate mismatch: got {got}, want {want}"
                            )));
                        }
                        Ok(())
                    }
                })
                .await)
        }
        LoadShape::Bidi => {
            let client = tonic_load_client(channel, max_message_size);
            let template = bidi_tonic_request(resp_bytes);
            Ok(load_gen
                .run(move || {
                    let client = client.clone();
                    let template = template.clone();
                    async move {
                        let mut client = client;
                        let (tx, rx) = tokio::sync::mpsc::channel(1);
                        let mut inbound = client
                            .full_duplex_call(tonic::Request::new(
                                tokio_stream::wrappers::ReceiverStream::new(rx),
                            ))
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .into_inner();
                        for i in 0..stream_msgs {
                            tx.send(template.clone()).await.map_err(|e| {
                                load::RpcCallError::Other(format!("bidi send pair {i}: {e}"))
                            })?;
                            let reply = inbound
                                .message()
                                .await
                                .map_err(|e| {
                                    load::RpcCallError::Other(format!("bidi recv pair {i}: {e}"))
                                })?
                                .ok_or_else(|| {
                                    load::RpcCallError::Other(format!(
                                        "bidi stream ended early at pair {i}"
                                    ))
                                })?;
                            if reply.payload().body().len() != resp_bytes {
                                return Err(load::RpcCallError::Other(format!(
                                    "bidi pair {i} size mismatch: got {}, want {resp_bytes}",
                                    reply.payload().body().len()
                                )));
                            }
                        }
                        drop(tx);
                        while inbound
                            .message()
                            .await
                            .map_err(|e| load::RpcCallError::Other(e.to_string()))?
                            .is_some()
                        {
                            return Err(load::RpcCallError::Other(
                                "bidi unexpected extra message after close".to_string(),
                            ));
                        }
                        Ok(())
                    }
                })
                .await)
        }
    }
}

async fn run_load_benchmark(_args: &[String], opts: LoadCliArgs) -> Result<(), String> {
    let distribution = opts.distribution.unwrap_or(if opts.rate.is_some() {
        load::LoadDistribution::Constant
    } else {
        load::LoadDistribution::Closed
    });

    let rate = match distribution {
        load::LoadDistribution::Closed => opts.rate,
        load::LoadDistribution::Constant | load::LoadDistribution::Poisson => {
            Some(opts.rate.unwrap_or(if opts.quick { 100.0 } else { 1000.0 }))
        }
    };

    let duration =
        Duration::from_secs_f64(
            opts.duration_secs
                .unwrap_or(if opts.quick { 0.5 } else { 2.0 }),
        );
    let mut cfg = match distribution {
        load::LoadDistribution::Closed => load::LoadConfig::closed(4, duration),
        load::LoadDistribution::Constant => {
            load::LoadConfig::open_constant(rate.unwrap(), duration)
        }
        load::LoadDistribution::Poisson => {
            let seed = opts.seed.unwrap_or(0x5eed_2026_0918);
            load::LoadConfig::open_poisson(rate.unwrap(), seed, duration)
        }
    };

    if let Some(cap) = opts.max_in_flight {
        cfg = cfg.with_max_in_flight(cap);
    }
    cfg = cfg.with_timeout(Duration::from_secs(5));

    let shape = opts.shape.unwrap_or(LoadShape::Unary);
    let transport = opts.transport.unwrap_or(LoadTransport::Native);
    let req_bytes = opts.req_bytes.unwrap_or(0);
    let resp_bytes = opts
        .resp_bytes
        .unwrap_or(if opts.benchmark_service { 1024 } else { 0 });
    let stream_msgs = opts.stream_msgs.unwrap_or(match shape {
        LoadShape::ServerStream => 2000,
        LoadShape::Bidi => 256,
        LoadShape::ClientStream => 8,
        LoadShape::Unary => 0,
    });

    println!(
        "running load benchmark: distribution={distribution}, rate={rate:?}, duration={duration:.1}s, max_in_flight={}, shape={shape}, transport={transport}, req_bytes={req_bytes}, resp_bytes={resp_bytes}, stream_msgs={stream_msgs}, tls={}",
        cfg.max_in_flight,
        opts.tls_ca.is_some(),
        duration = duration.as_secs_f64(),
    );

    let load_gen = load::LoadGenerator::new(cfg);

    let addr: SocketAddr = if let Some(ref addr_str) = opts.server_addr {
        addr_str
            .parse()
            .map_err(|e| format!("invalid --server_addr '{addr_str}': {e}"))?
    } else {
        if opts.tls_ca.is_some() {
            return Err(
                "TLS needs an explicit --server_addr: the loopback server is plaintext-only"
                    .to_string(),
            );
        }
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .map_err(|e| format!("failed to bind listener: {e}"))?;
        let bound = listener
            .local_addr()
            .map_err(|e| format!("failed to get local addr: {e}"))?;
        let max_message_size = opts.max_message_size;
        tokio::spawn(async move {
            let router = create_dual_server(max_message_size);
            let router = match max_message_size {
                Some(n) => router.max_decoding_message_size(n),
                None => router,
            };
            router.serve_listener(listener).await.ok();
        });
        tokio::time::sleep(Duration::from_millis(50)).await;
        bound
    };

    let connections = opts.connections.unwrap_or(1);
    let record = match transport {
        LoadTransport::Native => {
            run_load_native(
                &load_gen,
                addr,
                opts.tls_ca.as_deref(),
                opts.tls_server_name.as_deref(),
                shape,
                req_bytes,
                resp_bytes,
                stream_msgs,
                opts.benchmark_service,
                opts.max_message_size,
                connections,
            )
            .await?
        }
        LoadTransport::Tonic => {
            run_load_tonic(
                &load_gen,
                addr,
                shape,
                req_bytes,
                resp_bytes,
                stream_msgs,
                opts.max_message_size,
                connections,
            )
            .await?
        }
    };

    let metrics = record.to_rpc_metrics();
    let qps = if record.duration.as_secs_f64() > 0.0 {
        record.successful_calls as f64 / record.duration.as_secs_f64()
    } else {
        0.0
    };

    println!(
        "offered_calls={} dispatched_calls={} completed_calls={} successes={} failures={} timeouts={} queue_overflows={} throughput_qps={:.1}",
        record.offered_calls,
        record.dispatched_calls,
        record.completed_calls,
        record.successful_calls,
        record.failed_calls,
        record.timed_out_calls,
        record.rejected_calls,
        qps
    );

    if let Some(lag) = record.scheduling_lag_summary() {
        println!(
            "scheduling_lag_nanos: p50={} p99={} max={}",
            lag.p50, lag.p99, lag.max
        );
    }

    if let Some(e2e) = record.e2e_latency_distribution() {
        println!(
            "e2e_latency_nanos: p50={} p90={} p99={} max={}",
            e2e.p50_nanos, e2e.p90_nanos, e2e.p99_nanos, e2e.max_nanos
        );
    }

    if opts.print_json {
        let json = serde_json::to_string_pretty(&metrics)
            .map_err(|e| format!("serialization error: {e}"))?;
        println!("{json}");
    }

    if let Some(ref path) = opts.output_file {
        let json = serde_json::to_string_pretty(&metrics)
            .map_err(|e| format!("serialization error: {e}"))?;
        std::fs::write(path, json).map_err(|e| format!("failed to write output to {path}: {e}"))?;
        println!("saved metrics to {path}");
    }

    Ok(())
}

#[tokio::main]
async fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args
        .iter()
        .any(|a| a == "--help" || a == "-h" || a == "help")
    {
        println!("{}", extended_usage());
        std::process::exit(0);
    }

    if matches!(
        args.get(1).map(String::as_str),
        Some("fairness" | "fairness-server")
    ) {
        let server = args.get(1).map(String::as_str) == Some("fairness-server");
        let result = match fairness::parse_options(&args, server) {
            Ok(options) => {
                if server {
                    fairness::run_server(options).await
                } else {
                    fairness::run(options).await
                }
            }
            Err(err) => Err(err),
        };
        if let Err(err) = result {
            eprintln!("fairness diagnostic failed: {err}");
            std::process::exit(1);
        }
        return;
    }

    let load_opts = match parse_load_cli_args(&args) {
        Ok(opts) => opts,
        Err(err) => {
            eprintln!("Error: {err}");
            eprintln!("{}", extended_usage());
            std::process::exit(2);
        }
    };

    if args.get(1).map(String::as_str) == Some("load") {
        if let Err(e) = run_load_benchmark(&args, load_opts).await {
            eprintln!("Load benchmark failed: {e}");
            std::process::exit(1);
        }
        return;
    }

    if args.get(1).map(String::as_str) == Some("benchmark-server")
        || args.get(1).map(String::as_str) == Some("serve-both")
    {
        let bind_addr = args.get(2).map(String::as_str).unwrap_or("127.0.0.1:50051");
        let listener = match TcpListener::bind(bind_addr).await {
            Ok(l) => l,
            Err(e) => {
                eprintln!("failed to bind to {bind_addr}: {e}");
                std::process::exit(1);
            }
        };
        let local_addr = match listener.local_addr() {
            Ok(a) => a,
            Err(e) => {
                eprintln!("failed to get local addr: {e}");
                std::process::exit(1);
            }
        };
        println!(
            "READY port={} addr={} transport=native services=grpc.testing.TestService,grpc.testing.BenchmarkService",
            local_addr.port(),
            local_addr
        );
        if let Err(e) = create_dual_server(None).serve_listener(listener).await {
            eprintln!("Server error: {e}");
            std::process::exit(1);
        }
        return;
    }

    if args.get(1).map(String::as_str) == Some("worker") {
        let driver_port = get_arg_val(&args, "--driver_port")
            .or_else(|| get_arg_val(&args, "--driver-port"))
            .or_else(|| get_arg_val(&args, "--port"))
            .or_else(|| get_arg_val(&args, "-p"))
            .unwrap_or_else(|| "10010".to_string());

        let port: u16 = match driver_port.parse() {
            Ok(p) => p,
            Err(e) => {
                eprintln!("invalid --driver_port '{driver_port}': {e}");
                std::process::exit(2);
            }
        };

        let bind_addr = format!("0.0.0.0:{port}");
        let listener = match TcpListener::bind(&bind_addr).await {
            Ok(l) => l,
            Err(_) => match TcpListener::bind(format!("127.0.0.1:{port}")).await {
                Ok(l) => l,
                Err(e) => {
                    eprintln!("failed to bind to {bind_addr} or 127.0.0.1:{port}: {e}");
                    std::process::exit(1);
                }
            },
        };

        let local_addr = match listener.local_addr() {
            Ok(a) => a,
            Err(e) => {
                eprintln!("failed to get local addr: {e}");
                std::process::exit(1);
            }
        };

        println!(
            "READY port={} addr={} transport=native services=grpc.testing.WorkerService",
            local_addr.port(),
            local_addr
        );

        let (quit_tx, mut quit_rx) = tokio::sync::watch::channel(false);
        let worker_impl = worker_client::WorkerServiceImpl::with_shutdown(quit_tx);

        let shutdown = async move {
            while !*quit_rx.borrow() {
                if quit_rx.changed().await.is_err() {
                    break;
                }
            }
        };

        if let Err(e) = worker_server::WorkerServiceServer::new(worker_impl)
            .serve_with_shutdown(listener, shutdown)
            .await
        {
            eprintln!("Worker server error: {e}");
            std::process::exit(1);
        }
        return;
    }

    let role = match process::parse_args(&args) {
        Ok(role) => role,
        Err(err) => {
            eprintln!("Error: {err}");
            eprintln!("{}", extended_usage());
            std::process::exit(2);
        }
    };

    match role {
        process::ProcessRole::Server(cfg) => {
            if let Err(e) = process::run_server(cfg).await {
                eprintln!("Server error: {e}");
                std::process::exit(1);
            }
        }
        process::ProcessRole::Client(cfg) => {
            if let Err(e) = process::run_client(cfg).await {
                eprintln!("Client benchmark failed: {e}");
                std::process::exit(1);
            }
        }
        process::ProcessRole::Smoke(cfg) => {
            if let Err(e) = process::run_smoke(cfg).await {
                eprintln!("Smoke benchmark failed: {e}");
                std::process::exit(1);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_load_cli_args_valid_combinations() {
        let args = vec![
            "rpc-bench".to_string(),
            "--rate=1500.5".to_string(),
            "--distribution=poisson".to_string(),
            "--seed=999".to_string(),
            "--max-in-flight=50".to_string(),
        ];
        let opts = parse_load_cli_args(&args).unwrap();
        assert_eq!(opts.rate, Some(1500.5));
        assert_eq!(opts.distribution, Some(load::LoadDistribution::Poisson));
        assert_eq!(opts.seed, Some(999));
        assert_eq!(opts.max_in_flight, Some(50));

        let args_space = vec![
            "rpc-bench".to_string(),
            "--rate".to_string(),
            "2000".to_string(),
            "--distribution".to_string(),
            "constant".to_string(),
            "--seed".to_string(),
            "123".to_string(),
        ];
        let opts_space = parse_load_cli_args(&args_space).unwrap();
        assert_eq!(opts_space.rate, Some(2000.0));
        assert_eq!(
            opts_space.distribution,
            Some(load::LoadDistribution::Constant)
        );
        assert_eq!(opts_space.seed, Some(123));

        let args_closed = vec!["rpc-bench".to_string(), "--distribution=closed".to_string()];
        let opts_closed = parse_load_cli_args(&args_closed).unwrap();
        assert_eq!(
            opts_closed.distribution,
            Some(load::LoadDistribution::Closed)
        );
    }

    #[test]
    fn test_parse_load_cli_args_invalid_values() {
        // Invalid rate
        let args = vec!["rpc-bench".to_string(), "--rate=invalid".to_string()];
        assert!(parse_load_cli_args(&args).is_err());

        // Negative rate
        let args = vec!["rpc-bench".to_string(), "--rate=-5.0".to_string()];
        assert!(parse_load_cli_args(&args).is_err());

        // Invalid distribution
        let args = vec![
            "rpc-bench".to_string(),
            "--distribution=gaussian".to_string(),
        ];
        assert!(parse_load_cli_args(&args).is_err());

        // Invalid seed
        let args = vec!["rpc-bench".to_string(), "--seed=not_a_number".to_string()];
        assert!(parse_load_cli_args(&args).is_err());

        // Benchmark service flag
        let args_bench = vec!["rpc-bench".to_string(), "--benchmark-service".to_string()];
        let opts_bench = parse_load_cli_args(&args_bench).unwrap();
        assert!(opts_bench.benchmark_service);
    }

    fn load_args(extra: &[&str]) -> Vec<String> {
        let mut args = vec!["rpc-bench".to_string(), "load".to_string()];
        args.extend(extra.iter().map(|s| s.to_string()));
        args
    }

    #[test]
    fn test_parse_load_shape_payload_transport() {
        let opts = parse_load_cli_args(&load_args(&[
            "--shape=server_stream",
            "--req-bytes=1024",
            "--resp-bytes=65536",
            "--stream-msgs=2000",
            "--transport=tonic",
        ]))
        .unwrap();
        assert_eq!(opts.shape, Some(LoadShape::ServerStream));
        assert_eq!(opts.req_bytes, Some(1024));
        assert_eq!(opts.resp_bytes, Some(65536));
        assert_eq!(opts.stream_msgs, Some(2000));
        assert_eq!(opts.transport, Some(LoadTransport::Tonic));

        // Aliases.
        let opts = parse_load_cli_args(&load_args(&["--shape=stream"])).unwrap();
        assert_eq!(opts.shape, Some(LoadShape::ServerStream));
        let opts = parse_load_cli_args(&load_args(&["--shape=ping_pong"])).unwrap();
        assert_eq!(opts.shape, Some(LoadShape::Bidi));

        // Defaults stay unset (resolved at run time).
        let opts = parse_load_cli_args(&load_args(&[])).unwrap();
        assert_eq!(opts.shape, None);
        assert_eq!(opts.transport, None);
        assert_eq!(opts.tls_ca, None);
        assert_eq!(opts.connections, None);

        let opts = parse_load_cli_args(&load_args(&["--connections=8"])).unwrap();
        assert_eq!(opts.connections, Some(8));
        let opts = parse_load_cli_args(&load_args(&["--conns", "4"])).unwrap();
        assert_eq!(opts.connections, Some(4));
        assert!(parse_load_cli_args(&load_args(&["--connections=0"])).is_err());
        assert!(parse_load_cli_args(&load_args(&["--connections=257"])).is_err());
    }

    #[test]
    fn test_parse_load_shape_tls_validation() {
        // Unknown shape.
        assert!(parse_load_cli_args(&load_args(&["--shape=all"])).is_err());
        // Oversized payload.
        assert!(parse_load_cli_args(&load_args(&["--req-bytes=134217729"])).is_err());
        // Zero stream messages.
        assert!(parse_load_cli_args(&load_args(&["--stream-msgs=0"])).is_err());
        // Unknown transport.
        assert!(parse_load_cli_args(&load_args(&["--transport=go"])).is_err());
        // TLS needs both halves.
        assert!(parse_load_cli_args(&load_args(&["--tls-ca=/tmp/ca.pem"])).is_err());
        assert!(parse_load_cli_args(&load_args(&["--tls-server-name=localhost"])).is_err());
        // TLS + tonic is explicitly unsupported.
        assert!(
            parse_load_cli_args(&load_args(&[
                "--transport=tonic",
                "--tls-ca=/tmp/ca.pem",
                "--tls-server-name=localhost",
            ]))
            .is_err()
        );
        // BenchmarkService is native unary only.
        assert!(
            parse_load_cli_args(&load_args(&["--benchmark-service", "--transport=tonic",]))
                .is_err()
        );
        assert!(
            parse_load_cli_args(&load_args(&["--benchmark-service", "--shape=bidi",])).is_err()
        );
        // Valid TLS pair parses.
        let opts = parse_load_cli_args(&load_args(&[
            "--tls-ca=/tmp/ca.pem",
            "--tls-server-name=localhost",
        ]))
        .unwrap();
        assert_eq!(opts.tls_ca.as_deref(), Some("/tmp/ca.pem"));
        assert_eq!(opts.tls_server_name.as_deref(), Some("localhost"));
    }

    #[test]
    fn test_client_shape_vocabulary_not_rejected() {
        // The client role owns --shape=all/qps/upload; the load parser must
        // not reject those values when the role is not `load`.
        for shape in ["all", "qps", "upload", "unary", "stream", "ping_pong"] {
            let args = vec![
                "rpc-bench".to_string(),
                "client".to_string(),
                format!("--shape={shape}"),
            ];
            let opts = parse_load_cli_args(&args).unwrap();
            assert_eq!(opts.shape, None);
        }
    }

    #[tokio::test]
    async fn test_dual_server_mounts_both_services() {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();

        tokio::spawn(async move {
            create_dual_server(None).serve_listener(listener).await.ok();
        });
        tokio::time::sleep(Duration::from_millis(50)).await;

        let channel = pbrs_grpc::Channel::connect(addr).await.unwrap();

        // 1. Verify TestService is served
        let test_client = pbrs_grpc::TestServiceClient::new(channel.clone());
        let empty_resp = test_client
            .empty_call(pbrs_grpc::Request::new(pbrs_grpc::Empty::new()))
            .await;
        assert!(empty_resp.is_ok());

        // 2. Verify BenchmarkService is served on the same endpoint
        let bench_client = benchmark_service::BenchmarkServiceClient::new(channel);
        let mut req = benchmark_service::SimpleRequest::new();
        req.set_response_size(256);
        let bench_resp = bench_client.unary_call(pbrs_grpc::Request::new(req)).await;
        assert!(bench_resp.is_ok());
        assert_eq!(bench_resp.unwrap().into_inner().payload().body().len(), 256);
    }
}
